// Shared Pawvy brand assets + PDF document helpers — used across
// Consignment, Invoices, Delivery Orders, and SOA document generators.

export const LOGO_B64 = "data:image/png;base64,";



export const PAYNOW_QR_B64 = "data:image/jpeg;base64,";

export const PAWVY = {
  companyName: 'Pawvy Limited Partnership',
  uen: 'T23LP0163A',
  address: '91, Defu Lane 10\nSingapore 539221',
  contacts: ['+65 9689 4853 (Janice Lee)', '+65 9647 6576 (KT Goh)'],
  email: 'janicelee@pawvy.co',
  payNowUen: 'T23LP0163A',
  bank: 'UOB Current Account',
  account: '7723687857',
};

export const sgd = v => `SGD ${parseFloat(v||0).toFixed(2)}`;

/**
 * Renders the shared Pawvy document header (logo + title + date) used by
 * every printable document — Consignment List, Invoice, Delivery Order, SOA.
 */
export function pawvyHeaderHtml(title, dateLabel) {
  return `
  <div style="background:#14213d;padding:16px 32px;display:flex;align-items:center;justify-content:space-between">
    <img src="${LOGO_B64}" alt="Pawvy" style="height:80px;width:auto;object-fit:contain"/>
    <div style="text-align:right">
      <div style="font-size:22px;font-weight:700;color:#fff;letter-spacing:1px">${title}</div>
      <div style="color:#f36f4a;font-size:13px;font-weight:600;margin-top:4px">${dateLabel}</div>
    </div>
  </div>`;
}

/**
 * Renders the shared From / Bill To / Doc Number block.
 */
export function pawvyAddressBlockHtml(partner, docNum) {
  return `
  <div style="padding:24px 32px;display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #f0f2f5">
    <div>
      <div style="color:#666;font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-bottom:6px">From</div>
      ${PAWVY.address.split('\n').map(l=>`<div style="font-size:12px;color:#333;line-height:1.7">${l}</div>`).join('')}
      ${PAWVY.contacts.map(c=>`<div style="font-size:12px;color:#333;line-height:1.7">${c}</div>`).join('')}
      <div style="font-size:12px;color:#14213d;font-weight:600;margin-top:2px"><a href="mailto:${PAWVY.email}" style="color:#14213d">${PAWVY.email}</a></div>
    </div>
    <div>
      <div style="color:#666;font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-bottom:6px">Bill To</div>
      <div style="font-size:14px;font-weight:700;color:#14213d">${partner?.company_name || partner?.partner_name || '—'}</div>
      ${partner?.address ? `<div style="font-size:12px;color:#555;margin-top:3px;max-width:220px;line-height:1.5">${partner.address}</div>` : ''}
      ${partner?.pic_name ? `<div style="font-size:11px;color:#888;margin-top:4px">Attn: ${partner.pic_name}</div>` : ''}
    </div>
    <div style="text-align:right">
      <div style="font-size:20px;font-weight:700;color:#14213d;font-family:monospace">${docNum}</div>
      <div style="font-size:10px;color:#888;margin-top:4px">UEN: ${PAWVY.uen}</div>
    </div>
  </div>`;
}

export function pawvyFooterHtml(message) {
  return `
  <div style="text-align:center;padding:16px 32px;font-style:italic;font-size:15px;font-weight:600;color:#14213d">
    ${message || 'Thank you for the partnership !'}
  </div>
  <div style="background:#f36f4a;height:10px"></div>`;
}

/**
 * Payment instructions block with PayNow QR — matches the reference template:
 * underlined heading, two-column label:value rows, QR code below.
 */
export function pawvyPaymentInstructionsHtml() {
  return `
  <div style="padding:0 32px 24px">
    <div style="font-size:13px;font-weight:700;color:#14213d;text-decoration:underline;margin-bottom:10px">Payment Instructions:</div>
    <div style="display:flex;gap:60px;align-items:flex-start">
      <div style="flex-shrink:0">
        <table style="border-collapse:collapse;font-size:12px">
          <tr><td style="padding:3px 0;color:#222">- Paynow to UEN</td><td style="padding:3px 0 3px 16px;color:#222">: ${PAWVY.payNowUen}</td></tr>
          <tr><td style="padding:3px 0;color:#222">- Name</td><td style="padding:3px 0 3px 16px;color:#222">: ${PAWVY.companyName.toUpperCase()}</td></tr>
          <tr><td style="padding:3px 0;color:#222">- Bank Account</td><td style="padding:3px 0 3px 16px;color:#222">: ${PAWVY.account} (${PAWVY.bank})</td></tr>
        </table>
        <img src="${PAYNOW_QR_B64}" alt="PayNow QR" style="width:130px;height:auto;margin-top:12px;display:block"/>
      </div>
    </div>
  </div>`;
}

export function openPdfWindow(html) {
  const win = window.open('', '_blank');
  win.document.write(html);
  win.document.close();
  setTimeout(() => win.print(), 400);
}
